fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let max_len = m.max(n);

    // Helper closure to broadcast a single vector to length max_len
    // If vector length == max_len, clone it directly.
    // If length == 1, repeat the single element max_len times.
    let broadcast = |v: &Vec<i8>| -> Vec<i8> {
        match v.len() {
            len if len == max_len => v.clone(),
            1 => vec![v[0]; max_len],
            _ => unreachable!("Inputs are guaranteed compatible, so no other length is possible."),
        }
    };

    let a_broadcasted = broadcast(&a);
    let b_broadcasted = broadcast(&b);

    (a_broadcasted, b_broadcasted)
}